export function brandLogoSvg(id: string) {
  if (id === "goodman") {
    return `<img class="bs-logo-img" src="data:image/png;base64," alt="Goodman" />`;
  }
  if (id === "daikin") {
    return `<img class="bs-logo-img" src="data:image/png;base64," alt="Daikin" />`;
  }
  // acpro
  return `<img class="bs-logo-img" src="data:image/png;base64," alt="AC Pro" />`;
}
